/** Returns an AST or null when the grammar rejects the body. */
export function parse(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('syntax') }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, x: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.k === 'num') return { n: 'num', v: Number(t.v) }
    if (t.k === 'op') {
      if (t.v === '(') {
        const x = cmp()
        if (!isOp(')')) fail()
        p++
        return { n: 'paren', x }
      }
      fail()
    }
    const up = t.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { n: 'call', name: up, args }
    }
    if (up === 'TRUE') return { n: 'bool', v: true }
    if (up === 'FALSE') return { n: 'bool', v: false }
