      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      return { n: 'range', a: t.v, b: toks[p++].v }
    }
    return { n: 'ref', w: t.v }
  }
  try {
    const ast = cmp()
    if (p !== toks.length) return null
    return ast
  } catch {
    return null
  }
