#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { ERRORS, parse, parseAddress, deps, evaluate } from './formula.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
  const word = m[1].toUpperCase()
  const addr = parseAddress(word)
  if (!addr) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  if (cells.has(addr.key)) fail(`error: line ${i + 1}: cell ${addr.key} is declared twice`)
  const content = m[2]
  const cell = { ...addr, content }
  if (content[0] === '=') {
    cell.ast = parse(content.slice(1))
    cell.formula = true
  }
  cells.set(addr.key, cell)
})

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
const out = []

if (mode === 'deps') {
  for (const c of sorted) {
    const d = c.ast ? deps(c.ast) : []
    out.push(`${c.key}:${d.map((k) => ' ' + k).join('')}`)
  }
} else {
  const memo = new Map()
  const stack = new Set()
  const lookup = (key) => {
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return { t: 'n', v: 0 }
    if (stack.has(key)) return { t: 'e', v: '#CYCLE!' }
    let v
    if (c.formula) {
      if (!c.ast) v = { t: 'e', v: '#ERR!' }
      else {
        stack.add(key)
        v = evaluate(c.ast, lookup)
        stack.delete(key)
      }
    } else if (c.content === '') v = { t: 'n', v: 0 }
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c.content)) v = { t: 'n', v: Number(c.content) }
    else if (ERRORS.includes(c.content)) v = { t: 'e', v: c.content }
    else v = { t: 's', v: c.content }
    memo.set(key, v)
    return v
  }
  for (const c of sorted) {
    const v = lookup(c.key)
    let s
    if (v.t === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.t === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${c.key}=${s}`)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
