    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, x: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.k === 'num') return { n: 'num', v: Number(t.v) }
    if (t.k === 'op') {
      if (t.v === '(') {
        const x = cmp()
        if (!isOp(')')) fail()
        p++
        return { n: 'paren', x }
      }
      fail()
    }
    const up = t.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { n: 'call', name: up, args }
    }
    if (up === 'TRUE') return { n: 'bool', v: true }
    if (up === 'FALSE') return { n: 'bool', v: false }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      return { n: 'range', a: t.v, b: toks[p++].v }
    }
    return { n: 'ref', w: t.v }
  }
  try {
    const ast = cmp()
    if (p !== toks.length) return null
    return ast
  } catch {
    return null
  }
}

function misplacedRange(ast, direct = false) {
  switch (ast.n) {
    case 'range': return !direct
    case 'paren': return misplacedRange(ast.x)
    case 'un': return misplacedRange(ast.x)
    case 'bin': return misplacedRange(ast.l) || misplacedRange(ast.r)
    case 'call': return ast.args.some((a) => misplacedRange(a, true))
    default: return false
  }
}

function rangeCells(a, b) {
  const x = parseAddress(a), y = parseAddress(b)
  if (!x || !y) return null
  const out = []
  const c0 = Math.min(x.col, y.col), c1 = Math.max(x.col, y.col)
  const r0 = Math.min(x.row, y.row), r1 = Math.max(x.row, y.row)
  for (let c = c0; c <= c1; c++) for (let r = r0; r <= r1; r++) out.push({ col: c, row: r, key: colName(c) + r })
  return out
}

export function deps(ast) {
  const seen = new Map()
  const add = (a) => seen.set(a.key, a)
  const walk = (n) => {
    switch (n.n) {
      case 'ref': { const a = parseAddress(n.w); if (a) add(a); break }
      case 'range': { const cs = rangeCells(n.a, n.b); if (cs) cs.forEach(add); break }
      case 'paren': case 'un': walk(n.x); break
      case 'bin': walk(n.l); walk(n.r); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  return [...seen.values()].sort((a, b) => a.col - b.col || a.row - b.row).map((a) => a.key)
}

function toNum(v) {
  if (v.t === 'e') return v
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function kindRank(v) { return v.t === 'n' ? 0 : v.t === 's' ? 1 : 2 }
function cmpVals(a, b) {
  const ra = kindRank(a), rb = kindRank(b)
  if (ra !== rb) return ra - rb
  if (a.t === 's') {
    const x = Array.from(a.v), y = Array.from(b.v)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

/** Evaluates an AST; `lookup(key)` yields the value of a valid address. */
export function evaluate(ast, lookup) {
  if (misplacedRange(ast)) return err('#ERR!')
  const ev = (n) => {
    switch (n.n) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return ev(n.x)
      case 'ref': { const a = parseAddress(n.w); return a ? lookup(a.key) : err('#REF!') }
      case 'un': {
        const v = toNum(ev(n.x))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = ev(n.l)
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          if (l.t === 'e') return l
          const r = ev(n.r)
          if (r.t === 'e') return r
          const c = cmpVals(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'b', v: res }
        }
        const a = toNum(l)
        if (a.t === 'e') return a
        const b = toNum(ev(n.r))
        if (b.t === 'e') return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          default: return fin(Math.pow(a.v, b.v))
        }
      }
      case 'call': return call(n)
    }
  }
  const expand = (n) => {
    if (n.n === 'range') {
      const cs = rangeCells(n.a, n.b)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => lookup(c.key))
    }
    return [ev(n)]
  }
  const call = (n) => {
    const { name, args } = n
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'ABS' || name === 'IF') {
      if (args.length !== (name === 'ABS' ? 1 : 3)) return err('#ERR!')
      if (args.some((a) => a.n === 'range')) return err('#ERR!')
      if (name === 'ABS') {
        const v = toNum(ev(args[0]))
        return v.t === 'e' ? v : num(Math.abs(v.v))
      }
      const c = ev(args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? args[1] : args[2])
    }
    if (args.length < 1) return err('#ERR!')
    const vals = []
    for (const a of args) vals.push(...expand(a))
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
      case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
      case 'MIN': return num(Math.min(...nums))
      default: return num(Math.max(...nums))
    }
  }
  return ev(ast)
}
